/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.fnBookmark();
        scwin.fnInit();
        $(this).find("input:checkbox[name=ipt_bfrDsclsType]").click(async function() {
                if ($(this).attr("checked") === "checked") {
                    if (await $c.win.confirm("선택한 공시유형이 모두 초기화됩니다.\n진행하시겠습니까?")) {
                        scwin.fnClearDType();
                    } else {
                        $(this).removeAttr("checked");
                    }
                }
        });
        $(this).find("input:radio[name=marketType]").click(async function() {
                await scwin.fnCrossCheck($(this));
                scwin.fnShowKosdaqSeg($(this));
        });
        $(this).find("input:radio[name=kosdaqSegment]").click(async function() {
                await scwin.fnCrossCheck($(this));
        });
        $(this).find("select[name=business]").change(async function() {
                await scwin.fnCrossCheck($(this));
        });
        $(this).find("select[name=securities]").change(async function() {
                await scwin.fnCrossCheck($(this));
        });
        $(this).find("select[name=slc_enterprise]").change(async function() {
                await scwin.fnCrossCheck($(this));
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00300.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
