try { scwin.discloureArr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst00300' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.kosdaqSeg = $c.util.getComponent('kosdaqSeg');
        scwin.fnBookmarkSearch = fnBookmarkSearch;
        scwin.init_ctxDefaults();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst00300.onpageload' });
    }
};

