scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnInit = function () {
    let securities = $c.util.getComponent('slc_securities').getValue(); if (securities == null) { securities = ''; }
    let marketType = $c.util.getComponent('rd_marketType').getValue(); if (marketType == null) { marketType = ''; }
    const kosdaqSegment = $c.util.getComponent('rd_kosdaqSegment').getValue();
    if (marketType !== "") {
        $("#searchForm").find("input:radio[name=marketType]").removeAttr("checked");
        if (marketType === "1") {
            $("#searchForm").find("input:radio[id=rWertpapier]").attr("checked", "checked");
        } else {
            if (marketType === "2") {
                $("#searchForm").find("input:radio[id=rKosdaq]").attr("checked", "checked");
                if (kosdaqSegment) {
                    if (kosdaqSegment === "1") {
                        $("#searchForm").find("input:radio[id=rGlobal]").attr("checked", "checked");
                    } else {
                        if (kosdaqSegment === "2") {
                            $("#searchForm").find("input:radio[id=ipt_rGeneral]").attr("checked", "checked");
                        } else {
                            $("#searchForm").find("input:radio[id=rSeg]").attr("checked", "checked");
                        }
                    }
                } else {
                    $("#searchForm").find("input:radio[id=rSeg]").attr("checked", "checked");
                }
                scwin.kosdaqSeg.setStyle("display", "");
            } else {
                if (marketType === "6") {
                    $("#searchForm").find("input:radio[id=rKonex]").attr("checked", "checked");
                } else {
                    if (marketType === "4") {
                        $("#searchForm").find("input:radio[id=rBond]").attr("checked", "checked");
                    } else {
                        if (marketType === "3") {
                            $("#searchForm").find("input:radio[id=rDrv]").attr("checked", "checked");
                        } else {
                            $("#searchForm").find("input:radio[id=rAll]").attr("checked", "checked");
                        }
                    }
                }
            }
        }
    }
    if (securities !== "") {
        $("#searchForm").find("#securities").val(securities);
    }
    let flag = false;
    for (idx in scwin.discloureArr) {
        const key = scwin.discloureArr[idx];
        const val = $("#searchForm").find("#disclosureType" + key).val();
        if (val !== "") {
            flag = true;
            let str = val.split("|");
            $("#searchForm").find("input:checkbox[name=disclosureTypeArr" + key + "]").each(function() {
                    for (i in str) {
                        if (str[i] === $(this).val()) {
                            $(this).attr("checked", "checked");
                        }
                    }
            });
            const len = $("#searchForm").find("input:checkbox[name=disclosureTypeArr" + key + "]").length;
            if (len > 0) {
                if ($("#searchForm").find("input:checkbox[name=ipt_bfrDsclsType]").attr("checked") === "checked") {
                    $('input:checkbox[name="bfrDsclsType"]').removeAttr("checked");
                }
            }
        }
    }
    if (flag === false) {
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "1 ') */
    } else {
        let vBtnType = $c.util.getComponent('slc_settlementMonth').getValue(); if (vBtnType == null) { vBtnType = ''; }
        if (vBtnType !== '') {
            // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
            //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
            //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
            /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "vBtnType - 1 ') */
        } else {
            // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
            //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
            //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
            /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "7 ') */
        }
        $c.util.getComponent('cal_fromDate').setValue($c.util.getComponent('cal_fromDate').getValue());
        $c.util.getComponent('cal_toDate').setValue($c.util.getComponent('cal_toDate').getValue());
    }
    const scode = (String(((dma_pageContext.get("ipt_disclosureType") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_disclosureType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_disclosureType") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_disclosureType") ?? ""))));
    const sValue = (String(((dma_pageContext.get("ipt_disTypevalue") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_disTypevalue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_disTypevalue") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_disTypevalue") ?? ""))));
    const sName = (String(((dma_pageContext.get("disTypename") ?? "")) == null ? '' : ((dma_pageContext.get("disTypename") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("disTypename") ?? "")) == null ? '' : ((dma_pageContext.get("disTypename") ?? ""))));
    if (scode !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("disclosureType", sName);
        str = sValue.split("|");
        $("#searchForm").find("input:checkbox[name=disclosureTypeArr" + scode + "]").each(function() {
                for (i in str) {
                    if (str[i] === $(this).val()) {
                        $(this).attr("checked", "checked");
                        if (sName !== "" && sName === "6") {
                            $c.util.getComponent('ipt_reportNmTemp').setValue("신규상장");
                        }
                    }
                }
        });
        if ($("#searchForm").find("input:checkbox[name=ipt_bfrDsclsType]").attr("checked") === "checked") {
            $('input:checkbox[name="bfrDsclsType"]').removeAttr("checked");
        }
    }
    setTimeout(async function(){ await scwin.fnSearchInit() }, 300);
};

