 */
scwin.fnCrossCheck = async function (obj) {
    if (obj.val() !== "") {
        if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
            await $c.win.alert("해당 항목 선택시 회사명이 초기화 됩니다.");
