/**
 * @method
 * @name validationChk
 * @description validation Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validationChk = async function () {
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate(fromDate, toDate) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.date.addYear(fromDate, 3) < $c.date.addYear(toDate, 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    if (!await scwin.allValidCheck(toDate, fromDate)) {
        return;
    }
    return true;
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    setTimeout(function() {
            AKCDiv.setStyle("display", "none");
        }, 200);
    scwin.fnCloseAllDsclsLayer();
    scwin.fnDisclosureAllSetting();
    if (!await scwin.validationChk()) {
        return;
    }
    if (($c.util.getComponent("dma_fnDownloadReq").get("repIsuSrtCd") || '') !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "");
    }
    for (let i = 0; i < scwin.discloureArr.length; i++) {
        $("#searchForm > #disclosureType" + scwin.discloureArr[i]).val($("#searchForm > #pDisclosureType" + scwin.discloureArr[i]).val());
    }
    const popNm = $c.util.getComponent('ipt_reportNmPop').getValue();
    const tmpNm = $c.util.getComponent('ipt_reportNmTemp').getValue();
