        $c.util.getComponent('ipt_reportCd').setValue("");
    }
    const reportName = $c.util.getComponent('ipt_reportNmTemp').getValue().replace(/(\s*)/g, "");
    $c.util.getComponent("dma_fnDownloadReq").set("reportNm", reportName);
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        if ($("#searchForm").find("select[name=slc_enterprise]").val() !== "") {
            await $c.win.alert("회사명 검색조건이 존재하면 기업집단 값은 초기화 처리됩니다.");
            $("#searchForm").find("select[name=slc_enterprise]").val("");
        }
    }
    if ($c.util.getComponent("ipt_currentPageSize").getValue() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDetailsSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "details_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    if ($("#searchForm").find("input:checkbox[name=ipt_bfrDsclsType]").attr("checked") === "checked") {
        scwin.fnClearDType();
    }
};

