/**
 * @method
 * @name fnDisclosureType
 * @description fn Disclosure Type 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.fnDisclosureType = function (code) {
    const objDsclsType = $("#searchForm").find("a[id=dsclsType" + code + "]");
    const objDscLayer = $("#searchForm").find("section[id=dsclsLayer" + code + "]");
    if (objDscLayer.css("display") !== "none") {
        objDscLayer.css("display", "none");
        if (!$("#searchForm").find("input:checkbox[name=disclosureTypeArr" + code + "]").is(":checked")) {
            if (objDsclsType.hasClass("active")) {
                objDsclsType.removeClass("active");
            }
            objDsclsType.css("display", "none");
            objDsclsType.css("display", "");
        }
    } else {
        objDscLayer.css("display", "");
        if (!objDsclsType.hasClass("active")) {
            objDsclsType.addClass("active");
        }
    }
};

/**
 * @method
 * @name fnCheckAllDscls
 * @description fn Check All Dscls 처리
 * @param {*} typeCode typeCode
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllDscls = function (typeCode) {
    let isCheck = false;
    const allChk = $("#searchForm").find("input:checkbox[name=dsclsLayer" + typeCode + "_all]");
    if (allChk.attr("checked") === "checked") {
        isCheck = true;
    }
    $("#searchForm").find("input:checkbox[name=disclosureTypeArr" + typeCode + "]").each(function() {
            if (isCheck) {
                $(this).attr("checked", "checked");
            } else {
                $(this).removeAttr("checked");
            }
    });
};

