scwin.fnCloseAllDsclsLayer = function () {
    for (let i = 0; i < scwin.discloureArr.length; i++) {
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        $("#searchForm").find("a[id=dsclsType" + scwin.discloureArr[i] + "]").removeClass("active");
