};

/**
 * @method
 * @name fnDisclosureAllSetting
 * @description fn Disclosure All Setting 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnDisclosureAllSetting = function () {
    for (let i = 0; i < scwin.discloureArr.length; i++) {
        let varCheckSetting = "";
        const setName = $("#searchForm > #pDisclosureType" + scwin.discloureArr[i]);
        $("#searchForm").find("input:checkbox[name=disclosureTypeArr" + scwin.discloureArr[i] + "]").each(function() {
                if ($(this).attr("checked") === "checked") {
                    varCheckSetting += $(this).val() + "|";
                }
        });
        setName.val(varCheckSetting);
        if (varCheckSetting !== "") {
            const objDsclsType = $("#searchForm").find("a[id=dsclsType" + scwin.discloureArr[i] + "]");
            if (!objDsclsType.hasClass("active")) {
                objDsclsType.addClass("active");
            }
        }
    }
};

/**
 * @method
 * @name fnGetCookieComCode
 * @description fn Get Cookie Com Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnGetCookieComCode = async function () {
    const cookiesStr = scwin.fnGetCookie('krxComp');
    let totalArray;
    let newVal = "";
    let newComNm = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    if (totalArray) {
        for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
            const sCookieTemp = totalArray[i].split(",");
            if (i === 0) {
                newVal = newVal + sCookieTemp[1];
            } else {
                newVal = newVal + "," + sCookieTemp[1];
            }
            newComNm = sCookieTemp[2];
        }
    } else {
        await $c.win.alert("최근 검색한 회사가 없습니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", newVal);
    await scwin.fnSearch();
};

