scwin.fnClearDType = function () {
    $("#searchForm").find("input:checkbox").each(function() {
            const valName = $(this).attr("name");
            if (!(valName === "bfrDsclsType" || valName === "lastReport")) {
                $(this).removeAttr("checked");
            }
    });
